const $=s=>document.querySelector(s),field=$('#field'),context=field.getContext('2d'),status=$('#status'),storage={getItem:k=>localStorage.getItem(k),setItem:(k,v)=>localStorage.setItem(k,v),removeItem:k=>localStorage.removeItem(k)};
let owner=null,panel=null,grid=null,native=null,store=null,exchange=null,frameAbort=null,geometry=null,adapter=null,installing=false,disposed=false,initialReady=false;
const seedUrl=new URL('../source_recovery_r57/logical_workspace/native_world_selected_harbor_capture_r2/SOURCE_BEFORE_SHORE.json',import.meta.url);
const heldKeys=new Set();
function resetKeys(){heldKeys.clear()}
function update(v=owner?.getView()){const ready=initialReady&&!!owner?.fieldReady&&!installing;for(const e of document.querySelectorAll('[data-field]'))e.disabled=!ready;$('#start').disabled=disposed||installing||!!owner;$('#cold').disabled=disposed||installing||!!owner;$('#resume').disabled=!v?.paused;$('#retry-save').disabled=!v?.retryCommitAvailable||!!v?.paused;$('#retry-view').disabled=!v?.presentationError;
 if(v?.operationId)status.textContent=v.error?(v.possibleStorageWrite?'저장 결과 보류: 동일 저장만 재시도할 수 있습니다.':'진행 보류: '+v.error):v.presentationError?'화면 보류: '+v.presentationError:v.paused?'잠시 멈춤':v.sourceSettled?'저장 완료 · 마지막 연출 중':'동일한 원본 상태에서 진행 중';panel?.refresh();}
function report(e){status.textContent=String(e?.message??e);update()}
async function prepareFrame({world,snapshot,signal,fresh}){if(signal.aborted)throw Error('ENTRY_FRAME_ABORTED');const bridge=isNative(snapshot)?native:grid;await bridge.prepare();fresh();const frame=bridge.draw(context);fresh();if(!frame.gridReady&&!frame.nativeReady)throw Error(frame.reason??'ENTRY_FIELD_FRAME_REQUIRED');return{ready:true,position:structuredClone(snapshot.position)}}
async function install(runtime){if(disposed||installing||owner&&!owner.fieldReady)throw Error('ENTRY_INSTALL_HELD');installing=true;update();let next=null,nextGrid=null,nextNative=null,nextExchange=null,nextAbort=null;const old={owner,grid,native,exchange,frameAbort,store,initialReady};
 try{adapter??=await loadApprovedLatestRuntimeAdapter();geometry??=await prepareSelectedGeometry();nextAbort=new AbortController();let nextStore;
  next=createWildOwner({adapter,runtime,selectedGeometry:geometry,persist:s=>{nextStore.save('SLOT_1',s);return true},prepareFieldFrame:x=>prepareFrame(x),mount:controls=>{panel=mountWildPanel({root:$('#battle'),...controls,onError:report});return panel},onUpdate:v=>update(v),resetKeys,onFieldReady:r=>{initialReady=true;status.textContent=`완료 저장 ${r.revision} · ${r.outcome??'야생 출현 없음'}`;field.focus();update()}});
  next.withCompletedWorld(world=>{nextStore=createWorldStore(storage,world.catalog,world.host);nextExchange=createExperimentalExchange({world,storage});nextGrid=createOriginalGridReturnPresentation({world,signal:nextAbort.signal});nextNative=createSelectedWorldPresentation({world,signal:nextAbort.signal})});
  owner=next;grid=nextGrid;native=nextNative;exchange=nextExchange;frameAbort=nextAbort;store=nextStore;
  await next.withCompletedWorld(world=>prepareFrame({world,snapshot:world.snapshot(),signal:nextAbort.signal,fresh:()=>{if(disposed||owner!==next||nextAbort.signal.aborted||!next.fieldReady)throw Error('ENTRY_INSTALL_STALE')}}));
  initialReady=true;old.owner?.dispose();old.grid?.dispose();old.native?.dispose();old.exchange?.dispose();old.frameAbort?.abort();status.textContent='원본 항구 필드를 준비했습니다. 해안으로 한 칸 이동하면 원본 출현 확률이 적용됩니다.';field.focus();
 }catch(e){next?.dispose();nextGrid?.dispose();nextNative?.dispose();nextExchange?.dispose();nextAbort?.abort();owner=old.owner;grid=old.grid;native=old.native;exchange=old.exchange;frameAbort=old.frameAbort;store=old.store;initialReady=old.initialReady;throw e}finally{installing=false;update()}}
async function seed(){const response=await fetch(seedUrl);if(!response.ok)throw Error('ENTRY_FIXTURE_MISSING');return response.json()}
function run(fn){Promise.resolve().then(fn).catch(report)}
$('#start').addEventListener('click',()=>run(async()=>{if(owner||installing)return;await install(await seed())}));
$('#cold').addEventListener('click',()=>run(async()=>{if(owner||installing)return;try{const input=await seed();await install(input);const saved=store.load('SLOT_1');if(!saved)throw Error('완료 저장이 없습니다.');await install(saved)}catch(e){owner?.dispose();grid?.dispose();native?.dispose();exchange?.dispose();frameAbort?.abort();owner=null;grid=null;native=null;exchange=null;frameAbort=null;store=null;panel=null;initialReady=false;resetKeys();context.clearRect(0,0,field.width,field.height);update();throw e}}));
$('#step').addEventListener('click',()=>run(async()=>{if(!initialReady||!owner?.fieldReady)return;initialReady=false;update();try{await owner.start('up')}catch(e){if(owner.fieldReady)initialReady=true;throw e}finally{update()}}));
$('#resume').addEventListener('click',()=>run(()=>owner?.resume()));$('#retry-save').addEventListener('click',()=>run(()=>owner?.retryCommit()));$('#retry-view').addEventListener('click',()=>run(()=>owner?.retryPresentation()));
$('#save').addEventListener('click',()=>run(()=>{if(!initialReady)throw Error('ENTRY_SAVE_HELD');store.save('SLOT_1',owner.completedSnapshot());status.textContent='완료 상태를 저장했습니다.'}));
$('#export').addEventListener('click',()=>run(()=>{owner.completedSnapshot();$('#exchange').value=exchange.exportText();status.textContent='완료 상태 전체를 내보냈습니다.'}));
$('#import').addEventListener('click',()=>run(()=>{owner.completedSnapshot();exchange.importText($('#exchange').value,{slot:'SLOT_2'});status.textContent='별도 슬롯에 저장했습니다. 가져온 상태 이어하기로 명시적으로 불러올 수 있습니다.'}));
$('#load2').addEventListener('click',()=>run(async()=>{owner.completedSnapshot();const saved=exchange.readImported({slot:'SLOT_2'});if(!saved)throw Error('가져온 완료 저장이 없습니다.');await install(saved)}));
window.addEventListener('keydown',e=>{if(owner&&!owner.fieldReady&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','e','E',' '].includes(e.key)){heldKeys.clear();if(e.target===field)e.preventDefault()}});
window.addEventListener('keyup',e=>heldKeys.delete(e.code));window.addEventListener('blur',()=>{resetKeys();owner?.pause('blur')});document.addEventListener('visibilitychange',()=>{if(document.hidden){resetKeys();owner?.pause('hidden')}});
window.addEventListener('pagehide',e=>{resetKeys();if(e.persisted){owner?.pause('bfcache');return}disposed=true;owner?.dispose();grid?.dispose();native?.dispose();exchange?.dispose();frameAbort?.abort();geometry?.dispose()});update();

