// Original modules retain HTMLImage page-lifetime caches. Never close or poison shared originals.
const ROOT=new URL('../source_recovery_r57/logical_workspace/native_world_selected_s9_ship_ui_r1/original-assets/',import.meta.url),PINS=new Map(GRID_PINS.assets.map(a=>[a.path,Object.freeze({...a})]));let pagePreparation=null,pageReady=false,pageFailure=null;const cache=new Map();
const sha=async bytes=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(x=>x.toString(16).padStart(2,'0')).join('');
async function browserDecode(bytes){const url=URL.createObjectURL(new Blob([bytes]));try{return await browserImageLoader(url)}finally{URL.revokeObjectURL(url)}}
function preparePage({fetcher=globalThis.fetch?.bind(globalThis),decode=browserDecode}={}){return pagePreparation??=(async()=>{try{if(typeof fetcher!=='function'||typeof decode!=='function')throw Error('GRID_IMAGE_INPUTS');const load=src=>{const key=src.replace(/^\.\//,'');if(!PINS.has(key))return Promise.reject(Error('GRID_UNPINNED_ASSET'));if(!cache.has(key))cache.set(key,(async()=>{const pin=PINS.get(key),r=await fetcher(new URL(key,ROOT));if(!r.ok)throw Error('GRID_ASSET_FETCH');const bytes=await r.arrayBuffer();if(bytes.byteLength!==pin.bytes||await sha(bytes)!==pin.sha256)throw Error('GRID_ASSET_PIN');const image=await decode(bytes);if((image?.naturalWidth??image?.width)!==pin.width||(image?.naturalHeight??image?.height)!==pin.height)throw Error('GRID_IMAGE_SIZE');return image})());return cache.get(key)};
 await Promise.all([...PINS.keys()].map(load));await Promise.all([loadApprovedPlayers(load),loadApprovedSurf(load,{dpr:2}),loadApprovedTerrain(load),loadApprovedFieldProof(load),loadPrologueDecorations(load),loadApprovedEventMarker(load),...GRID_PINS.identities.filter(x=>!x.startsWith('PLAYER_')).map(id=>loadApprovedNPCs(load,id))]);if(terrainStats().loaded!==terrainStats().expected||approvedAtlasStatuses().some(x=>x.status!=='ready'))throw Error('GRID_ORIGINAL_LOADER_NOT_READY');pageReady=true;return true}catch(e){pageFailure=String(e?.message??e);throw e}})();}
export function createOriginalGridReturnPresentation({world,fetcher,decode,signal}={}){
 if(!(world instanceof CanonicalWorld))throw Error('GRID_WORLD_REQUIRED');if(!(signal instanceof AbortSignal))throw Error('GRID_SIGNAL');const sourceHost=world.host,sourceStory=world.story,sourceDefinition=world.definition;let dead=false,epoch=0,prepared=null,last=null,drawing=false;const environment=createEnvironmentService(createMockEnvironment());
 function check(){if(dead||signal.aborted)throw Error('GRID_BRIDGE_DISPOSED');if(world.host!==sourceHost||world.story!==sourceStory||world.definition!==sourceDefinition)throw Error('GRID_WORLD_REPLACED')}
 function capture(){check();if(world.busy||world.story.pendingCommit)throw Error('GRID_WORLD_BUSY');const s=world.snapshot();validateWorldLocation(s,world.host);if(!GRID_PINS.scope.includes(s.position.scene))return{s,stamp:null,supported:false};if(world.field.scene!==s.position.scene||world.field.x!==s.position.x||world.field.y!==s.position.y||world.field.facing!==s.position.facing)throw Error('GRID_PRESENTATION_POSE_MISMATCH');const bindings=GRID_PINS.maps.find(m=>m.mapId===s.position.scene);for(const actor of world.field.core.npcs){const known=bindings.actors.find(a=>a.id===actor.id);if(!known||known.assetId!==actor.fieldAssetId)throw Error('GRID_ACTOR_BINDING');if(known.identity&&!approvedNPCPose({...actor,assetId:actor.fieldAssetId}))throw Error('GRID_ACTOR_POSE');}check();if(world.busy||world.story.pendingCommit)throw Error('GRID_WORLD_BUSY');return{s,stamp:JSON.stringify([s.sessionId,s.revision,s.position,s.world.spatialMode,s.player.appearance,s.world.puzzles,world.field.core.npcs,world.field.core.sequence]),supported:true};}
 function fresh(stamp){const c=capture();check();if(!c.supported||c.stamp!==stamp)throw Error('GRID_WORLD_CHANGED');return c}
 function required(reason){return Object.freeze({status:'GRID_FRAME_REQUIRED',gridReady:false,reason,committedWorldUnchanged:true,inputEnabled:false})}
 function dispose(){if(dead)return;dead=true;epoch++;prepared=null;last=null;environment.stop();signal?.removeEventListener('abort',dispose)}signal?.addEventListener('abort',dispose,{once:true});
 return Object.freeze({async prepare(){const c=capture(),own=++epoch;prepared=null;last=null;if(!c.supported)return required('GRID_MAP_OUTSIDE_S6_GYM7_HARBOR_S9_MEMORIAL_SHIP_CLOSURE');try{await preparePage({fetcher,decode});fresh(c.stamp);if(own!==epoch)throw Error('GRID_PREPARE_SUPERSEDED');prepared=c.stamp;return Object.freeze({status:'GRID_PREPARED_NOT_DRAWN',gridReady:false,assets:PINS.size,pageCacheLifetime:true})}catch(e){if(dead||signal?.aborted)throw e;return required(String(e?.message??e))}},
 draw(ctx,{elapsedMs=0}={}){check();if(drawing)throw Error('GRID_DRAW_REENTRY');const c=capture();last=null;if(!c.supported||c.stamp!==prepared||!pageReady)return required(pageFailure??'MATCHING_GRID_FRAME_NOT_PREPARED');if(ctx?.canvas?.width!==1280||ctx.canvas.height!==720||ctx.isContextLost?.()||!Number.isFinite(elapsedMs)||elapsedMs<0)throw Error('GRID_CONTEXT');fresh(c.stamp);drawing=true;try{drawWorld(ctx,world,environment,elapsedMs,{diagnostics:false,actorHeight:38,sceneZoom:1});fresh(c.stamp);if(!approvedPlayerDrawStatus()?.imageReady||ctx.isContextLost?.()||ctx.canvas.width!==1280||ctx.canvas.height!==720)throw Error('GRID_DRAW_INCOMPLETE');fresh(c.stamp);last=Object.freeze({status:'ORIGINAL_GRID_CPU_FRAME_SUBMITTED',gridReady:true,mapId:c.s.position.scene,position:Object.freeze({...c.s.position}),revision:c.s.revision,originalRenderer:true,mode:'ORIGINAL_GRID_48',inputEnabled:false,physicalDisplayConfirmed:false,pageCacheLifetime:true});return last}finally{drawing=false}},
 dispose,get status(){try{const c=capture();return Object.freeze({disposed:false,gridReady:!!last&&c.supported&&prepared===c.stamp&&pageReady})}catch(e){return Object.freeze({disposed:dead,gridReady:false,reason:e.message})}}});
}

// Isolated verified media ownership. No engine, commands, source writes, or global image cache.
import {CanonicalWorld} from '../source_recovery_r57/logical_workspace/native_world_selected_harbor_capture_r2/source/world/service.mjs';
import {PROFILE} from '../source_recovery_r57/logical_workspace/native_world_selected_harbor_capture_r2/source/world/native-gym/profile.mjs';
import {approvedSpeciesArt,approvedSpeciesRect} from '../source_recovery_r57/logical_workspace/native_world_selected_harbor_capture_r2/source/approved-species.mjs';
import {approvedBattleBackground} from '../source_recovery_r57/logical_workspace/native_world_selected_harbor_capture_r2/source/art/approved-battle-backgrounds.mjs';
import {resolveBattleBackground} from '../source_recovery_r57/logical_workspace/native_world_selected_harbor_capture_r2/source/presentation/battle-background.mjs';
import {trainerPortraitRect,resolveTrainerPortrait} from '../source_recovery_r57/logical_workspace/native_world_selected_harbor_capture_r2/source/battle-v3/shared-battle-sequences.mjs';
import {coverBackgroundRect} from '../source_recovery_r57/logical_workspace/native_world_selected_harbor_capture_r2/source/art/integrated-battle-layout.mjs';
const base=new URL('../source_recovery_r57/public_checkout/dist/',import.meta.url);
const owners=new WeakMap();
const failure=code=>Object.assign(new Error(code),{code});
const defaultDecode=blob=>globalThis.createImageBitmap(blob);
const sha256=async bytes=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),x=>x.toString(16).padStart(2,'0')).join('');
/** Each lease closes every bitmap it owns once, including late decode after abort/timeout. */
export async function prepareWildBattleMedia({world,signal,fresh=()=>true,fetcher=globalThis.fetch,decode=defaultDecode,urlFor=art=>new URL(art.src,base).href,timeoutMs=30000}={}){
 if(!(world instanceof CanonicalWorld)||!signal||typeof signal.addEventListener!=='function'||world.busy||typeof fresh!=='function'||!Number.isFinite(timeoutMs)||timeoutMs<=0||timeoutMs>120000)throw failure('WILD_MEDIA_PREFLIGHT');
 if(owners.has(world))throw failure('WILD_MEDIA_OWNER_BUSY');
 const before=world.snapshot(),stamp=JSON.stringify(before),keys=['story','host','definition','adapter','catalog','field','rng','battleDriver'],identity=keys.map(k=>world[k]);
 const lifetime=new AbortController(),images=new Map(),closed=new WeakSet(),cleanupErrors=[],records=[];let dead=false,complete=false;
 const token={};owners.set(world,token);
 function close(image){if(!image||(typeof image!=='object'&&typeof image!=='function')||closed.has(image))return;closed.add(image);try{image.close()}catch(e){cleanupErrors.push(String(e.message))}}
 function dispose(){if(dead)return;dead=true;lifetime.abort();for(const image of images.values())close(image);images.clear();if(owners.get(world)===token)owners.delete(world);signal.removeEventListener('abort',dispose)}
 function check(){if(dead||signal.aborted||owners.get(world)!==token||keys.some((k,i)=>world[k]!==identity[i])||world.busy||JSON.stringify(world.snapshot())!==stamp)throw failure('WILD_MEDIA_STALE');if(fresh()===false)throw failure('WILD_MEDIA_STALE');if(dead||signal.aborted||keys.some((k,i)=>world[k]!==identity[i])||world.busy||JSON.stringify(world.snapshot())!==stamp)throw failure('WILD_MEDIA_STALE')}
 // Awaiting loaders is cancellable even when a supplied loader ignores AbortSignal.
 async function bounded(work,onLate){check();let settled=false,timer,onAbort;const task=Promise.resolve().then(()=>{check();return work()});
  const interrupted=new Promise((_,reject)=>{onAbort=()=>reject(failure('WILD_MEDIA_ABORTED'));lifetime.signal.addEventListener('abort',onAbort,{once:true});timer=setTimeout(()=>reject(failure('WILD_MEDIA_TIMEOUT')),timeoutMs);if(lifetime.signal.aborted)onAbort()});
  task.then(value=>{if(settled&&onLate)onLate(value)},()=>{});
  try{const value=await Promise.race([task,interrupted]);settled=true;return value}finally{settled=true;clearTimeout(timer);lifetime.signal.removeEventListener('abort',onAbort)}
 }
 signal.addEventListener('abort',dispose,{once:true});
 try{
  check();const profile=PROFILE.harborWild;
  if(before.position.scene!==profile.mapId||!['boy','girl'].includes(before.player.appearance)||!Array.isArray(before.party)||before.party.length<1||before.party.length>6)throw failure('WILD_MEDIA_SOURCE_SCOPE');
  const species=[...new Set([...before.party.map(m=>m.speciesId),...profile.table.slots.map(s=>s.speciesId)])];
  const fronts=new Map(species.map(id=>[id,approvedSpeciesArt({namespace:'canonical',speciesId:id},'front')]));
  const bg=approvedBattleBackground(resolveBattleBackground(world.definition.maps[profile.mapId]));
  if(bg?.assetId!=='battle.biome.COAST')throw failure('WILD_MEDIA_BACKGROUND');
  const portrait=resolveTrainerPortrait({playerCharacterId:before.player.appearance==='girl'?'PLAYER_FEMALE':'PLAYER_MALE'},'player');
  const assets=[...fronts.values(),bg,portrait],unique=new Map();
  for(const art of assets){if(!art?.src||! /^(?:\.\/)?assets\//.test(art.src)||!/^([a-f0-9]{64})$/.test(art.sha256)||!(art.width>0&&art.height>0))throw failure('WILD_MEDIA_DESCRIPTOR');if(art.source){const[x,y,w,h]=art.source;if(![x,y,w,h].every(Number.isFinite)||x<0||y<0||w<=0||h<=0||x+w>art.width||y+h>art.height)throw failure('WILD_MEDIA_CROP')}unique.set(art.src,art)}
  for(const art of unique.values()){
   check();const url=urlFor(art);check();const response=await bounded(()=>fetcher(url,{signal:lifetime.signal}));check();if(!response?.ok)throw failure('WILD_MEDIA_FETCH');
   const bytes=await bounded(()=>response.arrayBuffer());check();const hash=await bounded(()=>sha256(bytes));check();if(hash!==art.sha256)throw failure('WILD_MEDIA_HASH');if(art.bytes!==undefined&&bytes.byteLength!==art.bytes)throw failure('WILD_MEDIA_BYTES');
   const image=await bounded(()=>decode(new Blob([bytes]),{signal:lifetime.signal,art}),close);images.set(art.src,image);check();
   if(typeof image?.close!=='function'||(image.width??image.naturalWidth)!==art.width||(image.height??image.naturalHeight)!==art.height)throw failure('WILD_MEDIA_DIMENSIONS');
   records.push(Object.freeze({src:art.src,url,sha256:hash,bytes:bytes.byteLength,width:art.width,height:art.height}));
  }
  check();complete=true;
  const live=()=>{if(dead||!complete||signal.aborted)throw failure('WILD_MEDIA_NOT_READY')};
  const draw=(c,fn)=>{live();c.save();try{c.imageSmoothingEnabled=true;c.imageSmoothingQuality='high';return fn()}finally{c.restore()}};
  return Object.freeze({get ready(){return complete&&!dead&&!signal.aborted},dispose,get records(){return Object.freeze([...records])},get cleanupErrors(){return Object.freeze([...cleanupErrors])},
